    "src/Oracle.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {IEACAggregatorProxy} from "./interfaces/IEACAggregatorProxy.sol";
import "@pythnetwork/pyth-sdk-solidity/IPyth.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface IAPI3 {
    function read() external view returns (int224 value, uint32 timestamp);
    function api3ServerV1() external view returns (address);
}

// Note: Compatible with Chainlink Interface, returned value decimal is the same = 8
interface IRedstone {
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

struct PythConfig {
    address contractAddress;
    bytes32 id;
    uint256 heartbeat;
}

struct API3Config {
    address contractAddress;
    uint256 heartbeat;
}

struct RedstoneConfig {
    address contractAddress;
    uint256 heartbeat;
}

error NoAvailablePrice();

enum OracleType {
    Pyth,
    Redstone,
    API3
}

contract Oracle is Ownable, IEACAggregatorProxy {
    PythConfig public pythConfig;
    API3Config public api3Config;
    RedstoneConfig public redstoneConfig;
    string public name;
    mapping(OracleType => bytes) public oracleMap;
    OracleType[3] public oracleOrder;

    // Note: regardless of the heartbeat claimed by the oracle provider
    // we do not know whether they'd send the tx right on time or it might take some time for the tx to be confirmed in block
    uint256 public constant HEARTBEAT_BUFFER = 60;

    constructor(
        PythConfig memory _pythConfig,
        RedstoneConfig memory _redstoneConfig,
        API3Config memory _api3Config,
        string memory _name,
        OracleType[3] memory _oracleOrder
    ) Ownable(msg.sender) {
        name = _name;
        if (_pythConfig.contractAddress != address(0) && _pythConfig.id != bytes32(0) && _pythConfig.heartbeat != 0) {
            pythConfig = _pythConfig;
        }
        if (_redstoneConfig.contractAddress != address(0) && _redstoneConfig.heartbeat != 0) {
            redstoneConfig = _redstoneConfig;
        }
        if (_api3Config.contractAddress != address(0) && _api3Config.heartbeat != 0) {
            api3Config = _api3Config;
        }

        oracleMap[OracleType.Pyth] = abi.encodeWithSelector(this.getPythPrice.selector);
        oracleMap[OracleType.Redstone] = abi.encodeWithSelector(this.getRedstonePrice.selector);
        oracleMap[OracleType.API3] = abi.encodeWithSelector(this.getAPI3Price.selector);

        oracleOrder = _oracleOrder;
    }

    /////////////////////////////////////////
    //////////                     //////////
    //////////   ADMIN FUNCTIONS   //////////
    //////////                     //////////
    /////////////////////////////////////////
    function setPyth(PythConfig memory config) external onlyOwner {
        // allow setting contractAddress and pythID to zero address and zero bytes32 to disable this source
        pythConfig = config;
    }

    function setAPI3(API3Config memory config) external onlyOwner {
        // allow setting api3contractAddress to zero address to disable this source
        api3Config = config;
    }

    function setRedstone(RedstoneConfig memory config) external onlyOwner {
        // allow setting redstonecontractAddress to zero address to disable this source
        redstoneConfig = config;
    }

    function setOracleOrder(OracleType[3] memory order) external onlyOwner {
        oracleOrder = order;
    }

    /////////////////////////////////////////
    //////////                     //////////
    //////////   VIEW FUNCTIONS    //////////
    //////////                     //////////
    /////////////////////////////////////////

    function getPythPrice() public view returns (int256, uint256) {
        // check if pyth config available
        if (pythConfig.contractAddress == address(0)) {
            return (int256(0), 0);
        }
        // get price
        PythStructs.Price memory priceData = IPyth(pythConfig.contractAddress).getPriceUnsafe(pythConfig.id);
        // staleness check
        if (priceData.publishTime < block.timestamp - (pythConfig.heartbeat + HEARTBEAT_BUFFER)) {
            return (int256(0), 0);
        }
        // return answer
        return (int256(priceData.price), priceData.publishTime);
    }

    function getRedstonePrice() public view returns (int256, uint256) {
        // check if redstone config available
        if (redstoneConfig.contractAddress == address(0)) {
            return (int256(0), 0);
        }
        // get price
        (, int256 answer,, uint256 updatedAt,) = IRedstone(redstoneConfig.contractAddress).latestRoundData();
        // staleness check
        if (updatedAt < block.timestamp - (redstoneConfig.heartbeat + HEARTBEAT_BUFFER)) {
            return (int256(0), 0);
        }
        // return answer
        return (answer, updatedAt);
    }

    // Note: According to the doc https://docs.api3.org/guides/dapis/read-a-dapi/
    // returned value is of 18 decimals, different from Chainlink(8), Redstone(8), Pyth(8)
    function getAPI3Price() public view returns (int256, uint256) {
        // check if api3 config available
        if (api3Config.contractAddress == address(0)) {
            return (int256(0), 0);
        }
        // get price
        (int224 value, uint32 timestamp) = IAPI3(api3Config.contractAddress).read();
        // staleness check
        if (timestamp < block.timestamp - (api3Config.heartbeat + HEARTBEAT_BUFFER)) {
            return (int256(0), 0);
        }
        // 18 - 8 = 10; divide by 1e10 to downcase 18 decimals to 8 decimals
        int256 priceInEightDecimals = value / 1e10;
        return (priceInEightDecimals, uint256(timestamp));
    }

    function getPrice() public view returns (int256, uint256) {
        int256 price;
        uint256 timestamp;
        bool success;
        bytes memory data;
        for (uint256 i = 0; i < oracleOrder.length; i++) {
            (success, data) = address(this).staticcall(oracleMap[oracleOrder[i]]);
            if (!success) {
                continue;
            }
            (price, timestamp) = abi.decode(data, (int256, uint256));
            if (price > 0) {
                return (price, timestamp);
            }
        }
        revert NoAvailablePrice();
    }

    /////////////////////////////////////////
    //////////                     //////////
    ////////// CHAINLINK FUNCTIONS //////////
    //////////                     //////////
    /////////////////////////////////////////

    // Note: most functions are useless. Just to be compatible so that existing AAVE subgraphs won't break
    //       the only important function is latestAnswer(), which is called by AAVEOracle.sol
    function decimals() external pure override returns (uint8) {
        // always return 8 decimals in compliance to chainlink format
        // all oracles integrated shall conform to this
        return 8;
    }

    function latestAnswer() public view override returns (int256) {
        (int256 price,) = getPrice();
        return price;
    }

    function latestTimestamp() public view override returns (uint256) {
        (, uint256 timestamp) = getPrice();
        return timestamp;
    }

    function latestRound() external view override returns (uint256) {
        return latestTimestamp();
    }

    function getAnswer(uint256) external view override returns (int256) {
        return latestAnswer();
    }

    function getTimestamp(uint256) external view override returns (uint256) {
        return latestTimestamp();
    }

    function getRoundData(uint80 _roundId)
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (int256 price, uint256 timestamp) = getPrice();
        return (_roundId, price, timestamp, timestamp, _roundId);
    }

    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (int256 price, uint256 timestamp) = getPrice();
        roundId = uint80(timestamp);
        return (roundId, price, timestamp, timestamp, roundId);
    }
}
"
